describe("services/invitation-service", () => {
  // can(actor, "member:invite", …) — a member cannot invite, an admin can.
  it("refuses an invite from an actor without member:invite", async () => {
    const tenant = await createTenant("invite-forbidden", "growth");

    await expect(
      invitationService.inviteMember(tenant.actors.member, {
        orgId: tenant.org.id,
        email: "newperson@invite-forbidden.test",
        role: "member",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  // wouldExceedLimit(plan, "seats", seatsUsed) blocks the fourth seat on free.
  it("refuses an invite that would exceed the plan's seat quota", async () => {
    // The free plan tops out at 3 seats; createTenant already seeds 4 active
    // members (owner, admin, member, viewer), so the org starts over quota.
    const tenant = await createTenant("invite-seat-quota", "free");

    await expect(
      invitationService.inviteMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        email: "onemore@invite-seat-quota.test",
        role: "member",
      }),
    ).rejects.toThrow(/seats/);
  });

  // A bulk invite checks the seat quota once, for the whole batch.
  it("checks the seat quota once for a bulk invite", async () => {
    const tenant = await createTenant("invite-bulk-quota", "starter");

    // Bring the org to 9 of its 10 starter seats: 4 from createTenant, 5 more
    // inserted directly so only a single seat remains.
    for (let i = 0; i < 5; i += 1) {
      const user = await userRepo.insertUser({
        email: `filler${i}@invite-bulk-quota.test`,
        name: `Filler ${i}`,
        passwordHash: "seed",
      });
      await memberRepo.insertMember(tenant.org.id, user.id, "member", null);
    }
    await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(9);

    // A batch of two exceeds the one remaining seat; the check runs once for
    // the whole batch, so nothing is created — not even the first invite.
    await expect(
      invitationService.inviteMembers(tenant.actors.admin, {
        orgId: tenant.org.id,
        invites: [
          { email: "batch-a@invite-bulk-quota.test", role: "member" },
          { email: "batch-b@invite-bulk-quota.test", role: "member" },
        ],
      }),
    ).rejects.toThrow(/seats/);

    await expect(
      invitationRepo.countPendingInvitations(tenant.org.id),
    ).resolves.toBe(0);

    // The same-sized single invite fits inside the one remaining seat.
    await expect(
      invitationService.inviteMembers(tenant.actors.admin, {
        orgId: tenant.org.id,
        invites: [{ email: "batch-c@invite-bulk-quota.test", role: "member" }],
      }),
    ).resolves.toHaveLength(1);
  });

  // consumeRateLimit(orgId, "member:invite") throttles invite bursts.
  it("rate-limits invites per organization", async () => {
    const tenant = await createTenant("invite-rate-limit", "growth");
    rateLimitState.allowed = false;

    await expect(
      invitationService.inviteMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        email: "throttled@invite-rate-limit.test",
        role: "member",
      }),
    ).rejects.toThrow(/rate limit/);
  });

  // member.invited carries the email and the granted role.
  it("emits member.invited with the email and role", async () => {
    const tenant = await createTenant("invite-emit", "growth");

    let off: Unsubscribe | undefined;
    const received = await new Promise((resolve) => {
      off = subscribe("member.invited", (payload) => resolve(payload));
      void invitationService.inviteMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        email: "invitee@invite-emit.test",
        role: "admin",
      });
    });
    off?.();

    expect(received).toMatchObject({
      orgId: tenant.org.id,
      email: "invitee@invite-emit.test",
      role: "admin",
    });
  });

  // Accepting creates the membership and emits member.joined.
  it("emits member.joined when an invitation is accepted", async () => {
    const tenant = await createTenant("invite-accept", "growth");
    const rawToken = "a".repeat(32);

    await invitationRepo.insertInvitation(
      tenant.org.id,
      {
        orgId: tenant.org.id,
        email: "acceptor@invite-accept.test",
        role: "member",
        expiresInDays: 14,
      },
      tenant.userIds.admin,
      hashToken(rawToken),
    );

    const newUser = await userRepo.insertUser({
      email: "acceptor@invite-accept.test",
      name: "Acceptor",
      passwordHash: "seed",
    });

    let off: Unsubscribe | undefined;
    const received = await new Promise((resolve) => {
      off = subscribe("member.joined", (payload) => resolve(payload));
      void invitationService.acceptInvitation(newUser.id, { token: rawToken });
    });
    off?.();

    expect(received).toMatchObject({
      orgId: tenant.org.id,
      userId: newUser.id,
      role: "member",
    });

    await expect(
      memberRepo.findMember(tenant.org.id, newUser.id),
    ).resolves.not.toBeNull();
  });

  // An expired or revoked token is refused rather than silently accepted.
  it("refuses an expired or revoked invitation token", async () => {
    const tenant = await createTenant("invite-revoked", "growth");
    const revokedToken = "b".repeat(32);

    const invitation = await invitationRepo.insertInvitation(
      tenant.org.id,
      {
        orgId: tenant.org.id,
        email: "revoked@invite-revoked.test",
        role: "member",
        expiresInDays: 14,
      },
      tenant.userIds.admin,
      hashToken(revokedToken),
    );
    await invitationRepo.revokeInvitation(tenant.org.id, invitation.id);

    const newUser = await userRepo.insertUser({
      email: "revoked@invite-revoked.test",
      name: "Revoked",
      passwordHash: "seed",
    });

    await expect(
      invitationService.acceptInvitation(newUser.id, { token: revokedToken }),
    ).rejects.toThrow(/revoked/);

    const expiredToken = "c".repeat(32);
    await invitationRepo.insertInvitation(
      tenant.org.id,
      {
        orgId: tenant.org.id,
        email: "expired@invite-revoked.test",
        role: "member",
        expiresInDays: -1,
      },
      tenant.userIds.admin,
      hashToken(expiredToken),
    );

    const secondUser = await userRepo.insertUser({
      email: "expired@invite-revoked.test",
      name: "Expired",
      passwordHash: "seed",
    });

    await expect(
      invitationService.acceptInvitation(secondUser.id, { token: expiredToken }),
    ).rejects.toThrow(/expired/);
  });
});
/**
 * Emits `issue.overdue` exactly once per overdue issue.
 *
 * Owner C implements `@/server/jobs/overdue-issue-job`. `isOverdue()` itself is
 * covered by `tests/lib/date.test.ts`.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

const PAST = "2026-01-01T00:00:00.000Z";
const FUTURE = "2026-12-31T00:00:00.000Z";
const NOW = new Date("2026-06-01T07:00:00.000Z");

async function makeTenant(slug: string): Promise<Tenant> {
  const tenant = await createTenant(slug);
  await usageRepo.recomputeUsage(tenant.org.id);
  return tenant;
}

async function insertIssue(
  tenant: Tenant,
  overrides: Partial<{ title: string; assigneeId: (typeof tenant.userIds)["member"] | null; dueAt: string | null }>,
) {
  const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
  return issueRepo.insertIssue(
    issueInput(tenant.org.id, tenant.project.id, overrides),
    tenant.userIds.owner,
    number,
  );
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  resetOverdueTracking();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("jobs/overdue-issue-job", () => {
  it("selects only issues whose due date has passed", async () => {
    const tenant = await makeTenant("overdue-select");
    const overdue = await insertIssue(tenant, { title: "Late", dueAt: PAST });
    await insertIssue(tenant, { title: "Not yet", dueAt: FUTURE });

    const seen: string[] = [];
    detachers.push(
      subscribe("issue.overdue", (payload) => {
        seen.push(payload.issueId);
      }),
    );

    await runOverdueIssueJob(NOW);

    expect(seen).toEqual([overdue.id]);
  });

  it("ignores issues in a closed status", async () => {
    const tenant = await makeTenant("overdue-closed");
    const issue = await insertIssue(tenant, { title: "Closed but late", dueAt: PAST });
    await issueRepo.setIssueStatus(tenant.org.id, issue.id, "done");

    const seen: string[] = [];
    detachers.push(
      subscribe("issue.overdue", (payload) => {
        seen.push(payload.issueId);
      }),
    );

    await runOverdueIssueJob(NOW);

    expect(seen).not.toContain(issue.id);
  });

  it("ignores issues without a due date", async () => {
    const tenant = await makeTenant("overdue-no-due");
    const issue = await insertIssue(tenant, { title: "No due date", dueAt: null });

    const seen: string[] = [];
    detachers.push(
      subscribe("issue.overdue", (payload) => {
        seen.push(payload.issueId);
      }),
    );

    await runOverdueIssueJob(NOW);

    expect(seen).not.toContain(issue.id);
  });

  it("emits issue.overdue once per overdue issue", async () => {
    const tenant = await makeTenant("overdue-payload");
    const issue = await insertIssue(tenant, {
      title: "Assigned and late",
      dueAt: PAST,
      assigneeId: tenant.userIds.member,
    });

    const seen: Array<{ issueId: string; dueAt: string; assigneeId: string | null }> = [];
    detachers.push(
      subscribe("issue.overdue", (payload) => {
        seen.push({
          issueId: payload.issueId,
          dueAt: payload.dueAt,
          assigneeId: payload.assigneeId,
        });
      }),
    );

    const result = await runOverdueIssueJob(NOW);

    expect(seen).toHaveLength(1);
    expect(seen[0]).toEqual({
      issueId: issue.id,
      dueAt: toIsoTimestamp(new Date(PAST)),
      assigneeId: tenant.userIds.member,
    });
    expect(result.processed).toBe(1);
    expect(result.failed).toBe(0);
  });

  it("does not re-emit for an issue already reported", async () => {
    const tenant = await makeTenant("overdue-dedupe");
    const issue = await insertIssue(tenant, { title: "Still late", dueAt: PAST });

    const seen: string[] = [];
    detachers.push(
      subscribe("issue.overdue", (payload) => {
        seen.push(payload.issueId);
      }),
    );

    await runOverdueIssueJob(NOW);
    await runOverdueIssueJob(new Date(NOW.getTime() + 60_000));

    expect(seen).toEqual([issue.id]);
  });

  it("keeps each organization's issues in its own batch", async () => {
    const north = await makeTenant("overdue-north");
    const acme = await makeTenant("overdue-acme");
    const northIssue = await insertIssue(north, { title: "North late", dueAt: PAST });
    const acmeIssue = await insertIssue(acme, { title: "Acme late", dueAt: PAST });

    const seen: Array<{ orgId: string; issueId: string }> = [];
    detachers.push(
      subscribe("issue.overdue", (payload) => {
        seen.push({ orgId: payload.orgId, issueId: payload.issueId });
      }),
    );

    await runOverdueIssueJob(NOW);

    expect(seen).toContainEqual({ orgId: north.org.id, issueId: northIssue.id });
    expect(seen).toContainEqual({ orgId: acme.org.id, issueId: acmeIssue.id });
    for (const entry of seen) {
      if (entry.issueId === northIssue.id) expect(entry.orgId).toBe(north.org.id);
      if (entry.issueId === acmeIssue.id) expect(entry.orgId).toBe(acme.org.id);
    }
  });
});
