/** Snapshot every tenant table, including tables with no rows yet. */
function tenantRows(orgId: OrgId) {
  const sqlite = db.getDb()."'$client;
  const tables = sqlite.prepare("SELECT name FROM sqlite_master WHERE type = '"'table'\")
    .all() as { name: string }[];
  return Object.fromEntries(tables.filter(({ name }) => {
    const columns = sqlite.prepare("'`PRAGMA table_info("${name}")`).all() as { name: string }[];
    return columns.some((column) => column.name === "org_id");
  }).map(({ name }) => [name, sqlite.prepare(`SELECT * FROM "${name}" WHERE org_id = ? ORDER BY rowid`).all(orgId)]));
}

