    store.insert(db.searchIndex).values({ id: "inert-search", orgId: tenant.org.id, subjectKind: "issue", subjectId: issue.id, content: "preserved", indexedAt: stamp }).run();
    store.insert(db.webhookEndpoints).values({ id: "inert-hook", orgId: tenant.org.id, url: "https://example.com", secret: "secret", createdAt: stamp, updatedAt: stamp }).run();
    store.insert(db.webhookDeliveries).values({ id: "inert-delivery", orgId: tenant.org.id, endpointId: "inert-hook", eventType: "issue.created", payload: "{}", createdAt: stamp, updatedAt: stamp }).run();
    await orgRepo.archiveOrg(tenant.org.id);
