    store.insert(db.webhookDeliveries).values({ id: "purge-delivery", orgId, endpointId: "purge-hook", eventType: "issue.created", payload: "{}", createdAt: stamp, updatedAt: stamp }).run();
    store.insert(db.searchIndex).values({ id: "purge-search", orgId, subjectKind: "issue", subjectId: issue.id, content: "Test", indexedAt: stamp }).run();
